CREATE POLICY "site_images_read_all" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'site-images');
CREATE POLICY "site_images_admin_insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'site-images' AND private.has_role(auth.uid(), 'admin'::app_role));
CREATE POLICY "site_images_admin_update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'site-images' AND private.has_role(auth.uid(), 'admin'::app_role)) WITH CHECK (bucket_id = 'site-images' AND private.has_role(auth.uid(), 'admin'::app_role));
CREATE POLICY "site_images_admin_delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'site-images' AND private.has_role(auth.uid(), 'admin'::app_role));